// User role management helpers

import { db } from '../providers/index.js';
import { COLLECTIONS } from './database.js';
import { DEFAULT_ROLE } from '../constants/roles.js';

/**
 * Get user role from users collection
 */
export async function getUserRole(userId) {
    try {
        const result = await db.from(COLLECTIONS.USERS)
            .select('*')
            .eq('$id', userId)
            .exec();

        if (result.data && result.data.length > 0) {
            return result.data[0].role || DEFAULT_ROLE;
        }

        return DEFAULT_ROLE; // Default role
    } catch (error) {
        console.error('Failed to get user role:', error);
        return DEFAULT_ROLE;
    }
}

/**
 * Get user profile including role
 */
export async function getUserProfile(userId) {
    try {
        const result = await db.from(COLLECTIONS.USERS)
            .select('*')
            .eq('$id', userId)
            .exec();

        if (result.data && result.data.length > 0) {
            return { data: result.data[0], error: null };
        }

        return { data: null, error: new Error('User profile not found') };
    } catch (error) {
        console.error('Failed to get user profile:', error);
        return { data: null, error };
    }
}
